import { readTextIfExists, writeText } from './fsx.js';
import type { ProjectPaths } from './types.js';

export const DF_GITIGNORE_CONTENT = [
  '# generated by dfl – do not edit',
  '# personal config, runtime state and install manifest',
  'local.json',
  'state.json',
  'installed.json',
  '# skills rendered from *.md.hbs templates (may contain personal values)',
  '*/steps/**/*.md',
  '',
].join('\n');

export const MANAGED_MARKER = 'dfl (managed)';

export function writeDfGitignore(paths: ProjectPaths): boolean {
  return writeText(paths.dfGitignoreFile, DF_GITIGNORE_CONTENT);
}

function blockBounds(marker: string): { start: string; end: string } {
  return { start: `# >>> ${marker} >>>`, end: `# <<< ${marker} <<<` };
}

/**
 * Inserts or replaces a marked block in a gitignore-style file. An empty `lines`
 * array removes the block. Creates the file when needed. Returns true if changed.
 */
export function upsertManagedBlock(file: string, lines: string[], marker: string = MANAGED_MARKER): boolean {
  const { start, end } = blockBounds(marker);
  const current = readTextIfExists(file) ?? '';
  const eol = current.includes('\r\n') ? '\r\n' : '\n';
  const kept: string[] = [];
  let inside = false;
  for (const line of current.split(/\r?\n/)) {
    if (line.trim() === start) {
      inside = true;
      continue;
    }
    if (inside && line.trim() === end) {
      inside = false;
      continue;
    }
    if (!inside) kept.push(line);
  }
  while (kept.length > 0 && kept[kept.length - 1] === '') kept.pop();
  const unique = [...new Set(lines.filter((line) => line.trim() !== ''))];
  const parts: string[] = [...kept];
  if (unique.length > 0) {
    if (parts.length > 0) parts.push('');
    parts.push(start, ...unique, end);
  }
  const next = parts.length > 0 ? parts.join(eol) + eol : '';
  if (next === current) return false;
  if (next === '' && current === '') return false;
  return writeText(file, next);
}

export function removeManagedBlock(file: string, marker: string = MANAGED_MARKER): boolean {
  if (readTextIfExists(file) === undefined) return false;
  return upsertManagedBlock(file, [], marker);
}
